// ReferenceList defines model for ReferenceList.
type ReferenceList struct {
	References []Reference `json:"references"`

	// SearchedBase The naming context this looked in.
	SearchedBase *string `json:"searchedBase,omitempty"`

	// Truncated True when the search stopped early, so there are references this
	// does not list. A list that quietly omits some is worse than none
	// when the question is "what would break if I deleted this".
	//
	// Note that `false` does not make the list complete. It is the result
	// of a search, so it holds the referring entries *this session can
	// see*; one hidden by the access rules is absent exactly as one that
	// does not exist is, and nothing in the protocol distinguishes them.
	// The answer is "nothing I can see points at this", which is not the
	// same claim as "nothing points at this".
	//
	// That applies to a list with entries in it as much as to an empty
	// one: acting on three references you can see is no safer when there
	// is a fourth you cannot. Unlike the comparison, there is nothing to
	// detect here -- a Compare recovers absent-from-denied for an
	// attribute on an entry you can already read, and no operation says
	// "your search would have matched something you may not see".
	Truncated bool `json:"truncated"`
}

// Requirements defines model for Requirements.
